#!/usr/bin/env bash
# Run this from the ROOT of your React Native project (where package.json lives).
set -e
echo "Adding global error boundary..."

echo "  components/ErrorBoundary.js"
mkdir -p "$(dirname 'components/ErrorBoundary.js')"
echo '' | base64 --decode > 'components/ErrorBoundary.js'

echo "  App.js"
mkdir -p "$(dirname 'App.js')"
echo '' | base64 --decode > 'App.js'

echo "Done."
